package com.qiyun.hotel.domain.enums;

public enum OrderStatus {
    PENDING_PAYMENT("待支付"),
    CONFIRMED("已确认"),
    CHECKED_IN("已入住"),
    CHECKED_OUT("已退房"),
    CANCELLED("已取消");

    private final String label;
    OrderStatus(String label) { this.label = label; }
    public String label() { return label; }

    private static final Map<OrderStatus, Set<OrderStatus>> TRANSITIONS = new HashMap<>();
    static {
        TRANSITIONS.put(PENDING_PAYMENT, setOf(CONFIRMED, CANCELLED));
        TRANSITIONS.put(CONFIRMED, setOf(CHECKED_IN, CANCELLED));
        TRANSITIONS.put(CHECKED_IN, setOf(CHECKED_OUT));
        TRANSITIONS.put(CHECKED_OUT, Collections.emptySet());
        TRANSITIONS.put(CANCELLED, Collections.emptySet());
    }
    private static Set<OrderStatus> setOf(OrderStatus... s) { return new HashSet<>(Arrays.asList(s)); }

