```java
    public OrderVO create(CreateOrderRequest req) {
        HotelOrder existing = orderMapper.selectOne(new LambdaQueryWrapper<HotelOrder>().eq(HotelOrder::getRequestId, req.getRequestId()));
        if (existing != null) return assemble(existing);   // 幂等：重复提交返回同一订单

        try {
            return txTemplate.execute(status -> createInTx(req));
        } catch (DuplicateKeyException e) {
            // 并发重复提交撞 request_id 唯一索引：本事务已整体回滚（含库存扣减），返回已落库的订单
            HotelOrder winner = orderMapper.selectOne(new LambdaQueryWrapper<HotelOrder>().eq(HotelOrder::getRequestId, req.getRequestId()));
            if (winner != null) return assemble(winner);
            throw e;
        }
    }

    private OrderVO createInTx(CreateOrderRequest req) {
        LocalDate today = LocalDate.now(clock);
        DateRules.validate(req.getCheckIn(), req.getCheckOut(), today, props.getBooking().getMaxStayNights());

        RoomType roomType = roomTypeMapper.selectById(req.getRoomTypeId());
        if (roomType == null || !Boolean.TRUE.equals(roomType.getActive())) {
            throw new BizException(ErrorCode.ROOM_TYPE_NOT_FOUND, "房型不存在或已下架");
        }
        List<LocalDate> dates = DateRules.nightDates(req.getCheckIn(), req.getCheckOut());

        // ① 行锁锁定库存（按日期升序，防死锁）：H2/MySQL 均执行 SELECT ... FOR UPDATE
        List<DailyInventory> locked = inventoryMapper.lockByTypeAndDates(roomType.getId(), dates);
        if (locked.size() != dates.size()) throw new BizException(ErrorCode.INVENTORY_NOT_READY, "部分日期的房量库存尚未初始化，请联系管理员");

        // ② 校验房量充足（防超卖核心：锁内校验）
        for (DailyInventory inv : locked) {
            int remaining = inv.getTotalRooms() - inv.getSoldRooms();
            if (remaining < req.getRoomCount()) {
                throw new BizException(ErrorCode.INSUFFICIENT_INVENTORY,
                        String.format("%s 房量不足：剩余 %d 间，需要 %d 间", inv.getBizDate(), remaining, req.getRoomCount()));
            }
        }

        // ③ 按价格日历计价（支持周末/节假日差异化定价）
        List<DailyPrice> prices = priceMapper.selectList(new LambdaQueryWrapper<DailyPrice>()
                .eq(DailyPrice::getRoomTypeId, roomType.getId()).in(DailyPrice::getBizDate, dates));
        if (prices.size() != dates.size()) throw new BizException(ErrorCode.PRICE_NOT_READY, "部分日期价格未初始化，请联系管理员");
        BigDecimal total = prices.stream().map(DailyPrice::getPrice).reduce(BigDecimal.ZERO, BigDecimal::add)
                .multiply(BigDecimal.valueOf(req.getRoomCount()));

        // ④ 落单 + 状态流水 + 扣减库存（同一事务，任一步失败整体回滚）
        HotelOrder order = new HotelOrder();
        order.setOrderNo(orderNoGenerator.next());
        order.setRoomTypeId(roomType.getId());
        order.setCheckInDate(req.getCheckIn());
        order.setCheckOutDate(req.getCheckOut());
        order.setRoomCount(req.getRoomCount());
        order.setGuestName(req.getGuestName());
        order.setGuestPhone(req.getGuestPhone());
        order.setGuestIdNo(req.getGuestIdNo());
        order.setTotalPrice(total);
        order.setStatus(OrderStatus.PENDING_PAYMENT.name());
        order.setRequestId(req.getRequestId());
        LocalDateTime now = LocalDateTime.now(clock);
        order.setCreatedAt(now);
        order.setUpdatedAt(now);
        orderMapper.insert(order);

        writeLog(order.getId(), null, OrderStatus.PENDING_PAYMENT, "guest", "提交预订，已锁定房量");

        for (DailyInventory inv : locked) {
            inv.setSoldRooms(inv.getSoldRooms() + req.getRoomCount());
            inventoryMapper.updateById(inv);
        }
        log.info("订单创建成功 orderNo={} 金额={} 间数={} 日期={}~{}", order.getOrderNo(), total, req.getRoomCount(), req.getCheckIn(), req.getCheckOut());
        return assemble(order);
    }

    private void writeLog(Long orderId, OrderStatus from, OrderStatus to, String operator, String remark) {
        OrderLog l = new OrderLog();
        l.setOrderId(orderId); l.setFromStatus(from == null ? null : from.name()); l.setToStatus(to.name());
        l.setOperator(operator); l.setRemark(remark); l.setCreatedAt(LocalDateTime.now(clock));
        logMapper.insert(l);
    }

    private OrderVO assemble(HotelOrder order) {
        RoomType rt = roomTypeMapper.selectById(order.getRoomTypeId());
        List<OrderLog> logs = logMapper.selectList(new LambdaQueryWrapper<OrderLog>().eq(OrderLog::getOrderId, order.getId()).orderByAsc(OrderLog::getId));
        return OrderAssembler.toVO(order, rt, logs);
    }
}
