@Service
public class OrderService {
    ... deps: txTemplate, orderMapper, inventoryMapper, logMapper, roomTypeMapper, logMapper, clock

    public OrderVO pay(String orderNo) {
        return transition(orderNo, OrderStatus.CONFIRMED, "guest", "模拟支付成功", null);
    }
    public OrderVO cancel(String orderNo) {
        return transition(orderNo, OrderStatus.CANCELLED, "guest", "用户取消订单", null);
    }
    public OrderVO checkIn(String orderNo) {
        return transition(orderNo, OrderStatus.CHECKED_IN, "frontdesk", "办理入住", order -> {
            if (LocalDate.now(clock).isBefore(order.getCheckInDate())) {
                throw new BizException(ErrorCode.EARLY_CHECK_IN,
                        "未到入住日期（入住日 " + order.getCheckInDate() + "），不能提前办理入住");
            }
        });
    }
    public OrderVO checkOut(String orderNo) {
        return transition(orderNo, OrderStatus.CHECKED_OUT, "frontdesk", "办理退房", null);
    }

    private OrderVO transition(String orderNo, OrderStatus target, String operator, String remark, Consumer<HotelOrder> guard) {
        return txTemplate.execute(status -> {
            // 行锁读订单，防并发重复操作（如前台双人同时办理入住）
            HotelOrder order = orderMapper.selectForUpdateByOrderNo(orderNo);
            if (order == null) throw new BizException(ErrorCode.ORDER_NOT_FOUND, "订单不存在：" + orderNo);
            OrderStatus from = OrderStatus.valueOf(order.getStatus());
            if (guard != null) guard.accept(order);
            if (!from.canTransitionTo(target)) {
                throw new BizException(ErrorCode.INVALID_STATE_TRANSITION,
                        String.format("订单当前状态为「%s」，不允许执行该操作", from.label()));
            }
            order.setStatus(target.name());
            order.setUpdatedAt(LocalDateTime.now(clock));
            orderMapper.updateById(order);
            writeLog(order.getId(), from, target, operator, remark);

            // 取消释放库存：仅从占房状态取消时需要归还房量
            if (target == OrderStatus.CANCELLED && (from == OrderStatus.PENDING_PAYMENT || from == OrderStatus.CONFIRMED)) {
                List<LocalDate> dates = DateRules.nightDates(order.getCheckInDate(), order.getCheckOutDate());
                List<DailyInventory> locked = inventoryMapper.lockByTypeAndDates(order.getRoomTypeId(), dates);
                for (DailyInventory inv : locked) {
                    inv.setSoldRooms(Math.max(0, inv.getSoldRooms() - order.getRoomCount()));
                    inventoryMapper.updateById(inv);
                }
            }
            return assemble(order);
        });
    }

    public OrderVO detail(String orderNo) {
        HotelOrder order = orderMapper.selectOne(new LambdaQueryWrapper<HotelOrder>().eq(HotelOrder::getOrderNo, orderNo));
        if (order == null) throw new BizException(ErrorCode.ORDER_NOT_FOUND, "订单不存在：" + orderNo);
        return assemble(order);
    }

    public List<OrderVO> listByPhone(String phone) {
        List<HotelOrder> orders = orderMapper.selectList(new LambdaQueryWrapper<HotelOrder>()
                .eq(HotelOrder::getGuestPhone, phone).orderByDesc(HotelOrder::getId).last("LIMIT 50"));
        return assembleList(orders);
    }

    private List<OrderVO> assembleList(List<HotelOrder> orders) {
        if (orders.isEmpty()) return Collections.emptyList();
        // 批量装配，避免 N+1
        Map<Long, RoomType> types = roomTypeMapper.selectBatchIds(orders.stream().map(HotelOrder::getRoomTypeId).distinct().collect(Collectors.toList()))
                .stream().collect(Collectors.toMap(RoomType::getId, t -> t));
        List<Long> ids = orders.stream().map(HotelOrder::getId).collect(Collectors.toList());
        Map<Long, List<OrderLog>> logsMap = logMapper.selectList(new LambdaQueryWrapper<OrderLog>()
                .in(OrderLog::getOrderId, ids).orderByAsc(OrderLog::getId))
                .stream().collect(Collectors.groupingBy(OrderLog::getOrderId));
        return orders.stream().map(o -> OrderAssembler.toVO(o, types.get(o.getRoomTypeId()), logsMap.getOrDefault(o.getId(), Collections.emptyList()))).collect(Collectors.toList());
    }
}
