     *
     * <p>防超卖的关键：下单事务内先锁后校验再扣减，任何并发事务在同一批库存行上串行化；
     * 锁顺序固定为日期升序，避免交叉加锁死锁。
     */
    List<DailyInventory> lockByTypeAndDates(@Param("roomTypeId") Long roomTypeId,
                                            @Param("dates") List<LocalDate> dates);
