        List<LocalDate> dates = DateRules.nightDates(checkIn, checkOut);
        List<RoomType> types = roomTypeMapper.selectList(new LambdaQueryWrapper<RoomType>().eq(RoomType::getActive, true).orderByAsc(RoomType::getBasePrice));
