@Service
@RequiredArgsConstructor
public class FrontDeskService {
    private final HotelOrderMapper orderMapper;
    private final DailyInventoryMapper inventoryMapper;
    private final RoomTypeMapper roomTypeMapper;
    private final OrderLogMapper logMapper;
    private final Clock clock;

    public List<OrderVO> orders(String status, LocalDate date) {
        LambdaQueryWrapper<HotelOrder> qw = new LambdaQueryWrapper<HotelOrder>()
                .eq(status != null && !status.isEmpty(), HotelOrder::getStatus, status)
                .eq(date != null, HotelOrder::getCheckInDate, date)
                .orderByDesc(HotelOrder::getId)
                .last("LIMIT 200");
        return OrderAssembler.list(orderMapper.selectList(qw), roomTypeMapper, logMapper);
    }

    public FrontDeskStatsVO stats() {
        LocalDate today = LocalDate.now(clock);
        LambdaQueryWrapper<HotelOrder> qw = new LambdaQueryWrapper<>();
        long todayCheckIn = orderMapper.selectCount(new LambdaQueryWrapper<HotelOrder>()
                .eq(HotelOrder::getCheckInDate, today).eq(HotelOrder::getStatus, OrderStatus.CHECKED_IN.name()));
        long todayCheckOut = orderMapper.selectCount(new LambdaQueryWrapper<HotelOrder>()
                .eq(HotelOrder::getCheckOutDate, today).eq(HotelOrder::getStatus, OrderStatus.CHECKED_OUT.name()));
        long inHouse = orderMapper.selectCount(new LambdaQueryWrapper<HotelOrder>()
                .eq(HotelOrder::getStatus, OrderStatus.CHECKED_IN.name()));
        // 今日营业额：今日创建且未取消的订单
        List<HotelOrder> todayOrders = orderMapper.selectList(new LambdaQueryWrapper<HotelOrder>()
                .ge(HotelOrder::getCreatedAt, today.atStartOfDay())
                .ne(HotelOrder::getStatus, OrderStatus.CANCELLED.name()));
        BigDecimal revenue = todayOrders.stream().map(HotelOrder::getTotalPrice).reduce(BigDecimal.ZERO, BigDecimal::add);
        // 今日入住率：按房型汇总 sold/total
        List<DailyInventory> todayInvs = inventoryMapper.selectList(new LambdaQueryWrapper<DailyInventory>()
                .eq(DailyInventory::getBizDate, today));
        List<RoomType> types = roomTypeMapper.selectList(new LambdaQueryWrapper<RoomType>().eq(RoomType::getActive, true));
        Map<Long, RoomType> typeMap = types.stream().collect(Collectors.toMap(RoomType::getId, t -> t, (a,b)->a));
        // per-type aggregate
        Map<Long, int[]> agg = new HashMap<>(); // [0]=total [1]=sold
        for (DailyInventory inv : todayInvs) {
            int[] a = agg.computeIfAbsent(inv.getRoomTypeId(), k -> new int[2]);
            a[0] += inv.getTotalRooms(); a[1] += inv.getSoldRooms();
        }
        List<RoomTypeOccupancyVO> rows = new ArrayList<>();
        int totalAll = 0, soldAll = 0;
        for (Map.Entry<Long, int[]> e : agg.entrySet()) {
            RoomType rt = typeMap.get(e.getKey());
            if (rt == null) continue;
            RoomTypeOccupancyVO r = new RoomTypeOccupancyVO();
            r.setCode(rt.getCode()); r.setName(rt.getName());
            r.setTotal(e.getValue()[0]); r.setSold(e.getValue()[1]);
            r.setRate(percent(e.getValue()[1], e.getValue()[0]));
            rows.add(r);
            totalAll += e.getValue()[0]; soldAll += e.getValue()[1];
        }
        FrontDeskStatsVO vo = new FrontDeskStatsVO();
        vo.setTodayCheckIn((int) todayCheckIn);
        vo.setTodayCheckOut((int) todayCheckOut);
        vo.setInHouse((int) inHouse);
        vo.setTodayRevenue(revenue);
        vo.setOccupancyRate(percent(soldAll, totalAll));
        vo.setRoomTypes(rows);
        return vo;
    }

    private static BigDecimal percent(int sold, int total) {
        if (total == 0) return BigDecimal.ZERO;
        return BigDecimal.valueOf(sold).multiply(BigDecimal.valueOf(100))
                .divide(BigDecimal.valueOf(total), 1, RoundingMode.HALF_UP);
    }
}
