        LocalDate today = LocalDate.now(clock);
        LocalDate in = checkIn != null ? checkIn : today;
        LocalDate out = checkOut != null ? checkOut : today.plusDays(1);
        return ApiResponse.ok(availabilityService.query(in, out));
    }
}

