        insertType("DB", "大床房", "368.00", 8, "1.8米大床 · 含双早 · 免费WiFi · 45㎡");
        insertType("TW", "标准双床房", "328.00", 10, "1.2米双床 · 含双早 · 免费WiFi · 32㎡");
        insertType("SU", "豪华套房", "688.00", 3, "独立客厅 · 含双早 · 浴缸 · 迷你吧 · 80㎡");
