```java
class ConcurrencyTest extends BaseIntegrationTest {
    @Autowired private BookingService bookingService;

    @Test
    void tenThreadsRaceForOneRoom_noOversell() throws Exception {
        LocalDate today = FixedClockConfig.TODAY;
        Long typeId = seedRoomType("DB", "大床房", "368.00", 2);
        setSold(typeId, today, 1);       // 还剩 1 间
        setSold(typeId, today.plusDays(1), 1);

        int threads = 10;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch start = new CountDownLatch(1);
        AtomicInteger success = new AtomicInteger();
        AtomicInteger insufficient = new AtomicInteger();

        for (int i = 0; i < threads; i++) {
            final int idx = i;
            pool.submit(() -> {
                ready.countDown();
                try {
                    start.await();
                    CreateOrderRequest req = new CreateOrderRequest();
                    req.setRoomTypeId(typeId);
                    req.setCheckIn(today);
                    req.setCheckOut(today.plusDays(2));
                    req.setRoomCount(1);
                    req.setGuestName("并发客人" + idx);
                    req.setGuestPhone("1390000" + String.format("%04d", idx));
                    req.setRequestId(UUID.randomUUID().toString());
                    bookingService.create(req);
                    success.incrementAndGet();
                } catch (BizException e) {
                    if (e.getErrorCode() == ErrorCode.INSUFFICIENT_INVENTORY) {
                        insufficient.incrementAndGet();
                    } else {
                        throw new RuntimeException(e); // 其他异常视为用例失败
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }
        assertTrue(ready.await(10, TimeUnit.SECONDS));
        start.countDown();
        pool.shutdown();
        assertTrue(pool.awaitTermination(60, TimeUnit.SECONDS));

        // 断言：恰好 1 单成功，9 单因房量不足被拒
        assertEquals(1, success.get());
        assertEquals(9, insufficient.get());

        // 不变量：任何一晚售出都不超过总房量
        for (LocalDate d : Arrays.asList(today, today.plusDays(1))) {
            DailyInventory inv = inventoryMapper.selectOne(...eq type, eq date...);
            assertTrue(inv.getSoldRooms() <= inv.getTotalRooms(), "发生超卖: " + d);
            assertEquals(2, inv.getSoldRooms()); // 1(预占) + 1(抢到)
        }
        assertEquals(1, orderMapper.selectCount(null));
    }
}
```
