const puppeteer = require('puppeteer-core');
const fs = require('fs');

const BASE = 'http://localhost:8080';
const OUT = '/Users/fangsanpi/hotel-booking-system/docs/screenshots';
fs.mkdirSync(OUT, { recursive: true });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: 'new',
    args: ['--no-sandbox', '--force-color-profile=srgb'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1440, height: 1000, deviceScaleFactor: 2 });
  page.setDefaultTimeout(20000);

  const shot = async (name) => {
    await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))));
    await sleep(400);
    await page.screenshot({ path: `${OUT}/${name}`, fullPage: true });
    console.log('shot:', name);
  };
  const waitChildren = (sel) =>
    page.waitForFunction(
      (s) => document.querySelector(s) && document.querySelector(s).children.length > 0,
      {},
      sel
    );
  const clickByText = async (rootSel, text) => {
    const ok = await page.evaluate(
      ({ rootSel, text }) => {
        const root = document.querySelector(rootSel);
        if (!root) return false;
        const btn = Array.from(root.querySelectorAll('button')).find(
          (b) => b.textContent.trim().includes(text) && !b.disabled
        );
        if (!btn) return false;
        btn.click();
        return true;
      },
      { rootSel, text }
    );
    if (!ok) throw new Error('button not found in ' + rootSel + ': ' + text);
  };
  const setByLabel = async (rootSel, labelText, value) => {
    const ok = await page.evaluate(
      ({ rootSel, labelText, value }) => {
        const root = document.querySelector(rootSel);
        if (!root) return false;
        const label = Array.from(root.querySelectorAll('label')).find((l) =>
          l.textContent.includes(labelText)
        );
        if (!label) return false;
        const input = label.querySelector('input');
        if (!input) return false;
        input.value = value;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
      },
      { rootSel, labelText, value }
    );
    if (!ok) throw new Error('input not found in ' + rootSel + ': ' + labelText);
  };

  // 1. 预订页（默认今明两晚，进入即自动加载房态）
  await page.goto(BASE + '/#/booking', { waitUntil: 'networkidle0' });
  await waitChildren('#bk-list');
  await sleep(300);
  await shot('01-预订-房态查询.png');

  // 2. 预订大床房 → 入住人表单
  await clickByText('#bk-list', '预订');
  await page.waitForFunction(() => {
    const s = document.querySelector('#bk-step2');
    return s && !s.hidden;
  });
  await setByLabel('#bk-step2', '姓名', '演示客人');
  await setByLabel('#bk-step2', '手机号', '13912345678');
  await shot('02-预订-填写入住人.png');

  // 3. 提交 → 结果卡（待支付）
  await clickByText('#bk-step2', '提交');
  await page.waitForFunction(() => {
    const s = document.querySelector('#bk-step3');
    return s && !s.hidden;
  });
  await sleep(300);
  await shot('03-预订-下单成功待支付.png');

  // 4. 模拟支付 → 已确认
  await clickByText('#bk-step3', '模拟支付');
  await sleep(700);
  await shot('04-预订-支付已确认.png');

  // 5. 订单查询：张伟（演示单）+ 状态时间线
  await page.goto(BASE + '/#/orders', { waitUntil: 'networkidle0' });
  await page.type('#od-input', '13800138001');
  await page.click('#od-search');
  await waitChildren('#od-results');
  await sleep(300);
  await page.evaluate(() => {
    const c = document.querySelector('#od-results .card') || document.querySelector('#od-results > div > div');
    if (c) c.click();
  });
  await sleep(300);
  await shot('05-订单查询-状态时间线.png');

  // 6. 前台管理：统计卡片 + 入住率图表 + 订单表
  await page.goto(BASE + '/#/frontdesk', { waitUntil: 'networkidle0' });
  await waitChildren('#fd-stats');
  await waitChildren('#fd-tbody');
  await sleep(300);
  await shot('06-前台管理-统计与订单.png');

  // 7. 为张伟办理入住
  const done = await page.evaluate(() => {
    const rows = Array.from(document.querySelectorAll('#fd-tbody tr'));
    const row = rows.find((r) => r.textContent.includes('张伟'));
    if (!row) return false;
    const btn = Array.from(row.querySelectorAll('button')).find((b) =>
      b.textContent.includes('办理入住')
    );
    if (!btn) return false;
    btn.click();
    return true;
  });
  if (!done) throw new Error('张伟 check-in button not found');
  await sleep(800);
  await shot('07-前台管理-办理入住.png');

  await browser.close();
  console.log('ALL SHOTS DONE');
})().catch((e) => {
  console.error('FAILED:', e.message);
  process.exit(1);
});

